import { getStores } from '../pigeon/store.js';

export interface ConversationSummary {
  contact: string;
  assignee: string | null;
}

// Newest first, paginated by offset. Minimal inbox listing.
export async function listConversations(workspace: string, limit: number, offset: number): Promise<ConversationSummary[]> {
  const { contacts } = await getStores();
  const rows = await contacts.find({ workspace }).sort({ created_at: -1, contact: 1 }).skip(offset).limit(limit).toArray();
  return rows.map((c) => ({ contact: c.contact, assignee: c.assignee ?? null }));
}
