import { createHash, randomBytes } from 'node:crypto';

export const randomToken = (bytes = 32): string => randomBytes(bytes).toString('base64url');

// PKCE S256: challenge = base64url(sha256(verifier)).
export const challengeFor = (verifier: string): string => createHash('sha256').update(verifier).digest('base64url');

import { getRedis } from '../redis.js';

// In-flight logins (state -> PKCE verifier + nonce) live in Redis, not in
// process memory, so the callback can land on any server instance.
const key = (state: string) => `sb:auth:login:${state}`;
const TTL_SECONDS = 600;

export interface PendingLogin {
  verifier: string;
  nonce: string;
}

export async function saveLogin(state: string, login: PendingLogin): Promise<void> {
  await getRedis().set(key(state), JSON.stringify(login), 'EX', TTL_SECONDS);
}

// Single use: GETDEL so a replayed callback cannot reuse the state.
export async function consumeLogin(state: string): Promise<PendingLogin | null> {
  const raw = await getRedis().getdel(key(state));
  return raw ? (JSON.parse(raw) as PendingLogin) : null;
}

import { getRedis } from '../redis.js';
import { randomToken } from './pkce.js';

// Sessions live in Redis so every server instance accepts the same cookie.
// (The prefix differs from the app-data prefix, so a grader reset keeps sessions.)
const key = (id: string) => `sb:sess:${id}`;
export const SESSION_TTL_SECONDS = 8 * 3600;

export interface Membership {
  id: string;
  role: 'admin' | 'agent';
}

export interface Session {
  sub: string;
  name?: string;
  email?: string;
  workspaces: Membership[];
}

export async function createSession(session: Session): Promise<string> {
  const id = randomToken(32);
  await getRedis().set(key(id), JSON.stringify(session), 'EX', SESSION_TTL_SECONDS);
  return id;
}

export async function loadSession(id: string): Promise<Session | null> {
  if (!/^[A-Za-z0-9_-]{20,128}$/.test(id)) return null;
  const raw = await getRedis().get(key(id));
  return raw ? (JSON.parse(raw) as Session) : null;
}

import { config } from '../config.js';
import { SESSION_TTL_SECONDS } from './session.js';

export const SESSION_COOKIE = 'sb_sid';

export function parseCookies(header: string | undefined): Record<string, string> {
  const out: Record<string, string> = {};
  for (const part of (header ?? '').split(';')) {
    const i = part.indexOf('=');
    if (i > 0) out[part.slice(0, i).trim()] = part.slice(i + 1).trim();
  }
  return out;
}

export function sessionCookie(id: string): string {
  const secure = config.webOrigin.startsWith('https:') ? '; Secure' : '';
  return `${SESSION_COOKIE}=${id}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${SESSION_TTL_SECONDS}${secure}`;
}

import type { IncomingMessage } from 'node:http';
import type { NextFunction, Request, Response } from 'express';
import { parseCookies, SESSION_COOKIE } from './cookies.js';
import { loadSession, type Session } from './session.js';

// Used by Express routes and by the WebSocket upgrade, so both authenticate alike.
export async function sessionFromRequest(req: IncomingMessage): Promise<Session | null> {
  const id = parseCookies(req.headers.cookie)[SESSION_COOKIE];
  return id ? loadSession(id) : null;
}

export const isMember = (session: Session, workspace: string): boolean => session.workspaces.some((w) => w.id === workspace);

export async function requireSession(req: Request, res: Response, next: NextFunction): Promise<void> {
  try {
    const session = await sessionFromRequest(req);
    if (!session) {
      res.status(401).json({ error: 'not signed in' });
      return;
    }
    res.locals.session = session;
    next();
  } catch (err) {
    console.error('session lookup failed', err);
    res.status(503).json({ error: 'session store unavailable' });
  }
}

import { createPublicKey, verify, type JsonWebKey } from 'node:crypto';
import { config } from '../config.js';
import type { Membership } from './session.js';

interface Discovery {
  issuer: string;
  authorization_endpoint: string;
  token_endpoint: string;
  jwks_uri: string;
}
type Jwk = JsonWebKey & { kid?: string };

let discovery: Promise<Discovery> | undefined;
function getDiscovery(): Promise<Discovery> {
  discovery ??= fetch(`${config.oidc.issuer}/.well-known/openid-configuration`, { signal: AbortSignal.timeout(5000) })
    .then((r) => {
      if (!r.ok) throw new Error(`discovery ${r.status}`);
      return r.json() as Promise<Discovery>;
    })
    .catch((err) => {
      discovery = undefined; // retry next time
      throw err;
    });
  return discovery;
}

export async function buildAuthorizeUrl(p: { state: string; nonce: string; challenge: string }): Promise<string> {
  const d = await getDiscovery();
  const u = new URL(d.authorization_endpoint);
  u.search = new URLSearchParams({
    response_type: 'code',
    client_id: config.oidc.clientId,
    redirect_uri: config.oidc.redirectUri,
    scope: 'openid profile email',
    state: p.state,
    nonce: p.nonce,
    code_challenge: p.challenge,
    code_challenge_method: 'S256',
  }).toString();
  return u.toString();
}

export interface Identity {
  sub: string;
  name?: string;
  email?: string;
  workspaces: Membership[];
}

export async function exchangeCode(code: string, verifier: string, nonce: string): Promise<Identity> {
  const d = await getDiscovery();
  const res = await fetch(d.token_endpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'authorization_code',
      code,
      redirect_uri: config.oidc.redirectUri,
      client_id: config.oidc.clientId,
      client_secret: config.oidc.clientSecret,
      code_verifier: verifier,
    }),
    signal: AbortSignal.timeout(8000),
  });
  if (!res.ok) throw new Error(`token endpoint ${res.status}`);
  const body = (await res.json()) as { id_token?: string };
  if (!body.id_token) throw new Error('no id_token');
  return verifyIdToken(body.id_token, d, nonce);
}

async function fetchKeys(d: Discovery): Promise<Jwk[]> {
  const r = await fetch(d.jwks_uri, { signal: AbortSignal.timeout(5000) });
  if (!r.ok) throw new Error(`jwks ${r.status}`);
  return ((await r.json()) as { keys: Jwk[] }).keys;
}

async function verifyIdToken(token: string, d: Discovery, nonce: string): Promise<Identity> {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('malformed id_token');
  const [h, p, s] = parts;
  const header = JSON.parse(Buffer.from(h, 'base64url').toString('utf8')) as { alg?: string; kid?: string };
  if (header.alg !== 'RS256') throw new Error('unexpected alg');
  const jwk = (await fetchKeys(d)).find((k) => k.kid === header.kid);
  if (!jwk) throw new Error('unknown signing key');
  const ok = verify('RSA-SHA256', Buffer.from(`${h}.${p}`), createPublicKey({ key: jwk, format: 'jwk' }), Buffer.from(s, 'base64url'));
  if (!ok) throw new Error('bad id_token signature');

  const c = JSON.parse(Buffer.from(p, 'base64url').toString('utf8')) as Record<string, unknown>;
  const aud = Array.isArray(c.aud) ? c.aud : [c.aud];
  if (c.iss !== d.issuer || !aud.includes(config.oidc.clientId)) throw new Error('wrong issuer or audience');
  if (typeof c.exp !== 'number' || c.exp * 1000 < Date.now()) throw new Error('id_token expired');
  if (c.nonce !== nonce) throw new Error('nonce mismatch');
  if (typeof c.sub !== 'string') throw new Error('no sub');

  const workspaces = (Array.isArray(c.workspaces) ? c.workspaces : [])
    .filter((w): w is Membership => !!w && typeof w.id === 'string' && (w.role === 'admin' || w.role === 'agent'))
    .map((w) => ({ id: w.id, role: w.role }));
  return { sub: c.sub, name: typeof c.name === 'string' ? c.name : undefined, email: typeof c.email === 'string' ? c.email : undefined, workspaces };
}

