import { getRedis } from '../redis.js';

// Cross-instance wake-ups. The payload is only the workspace: the database is
// the source of truth for events, so a lost or duplicated wake-up cannot lose
// or duplicate a frame.
const PREFIX = 'sb:rt:';

type Listener = () => void;
const listeners = new Map<string, Set<Listener>>();
let subscribed = false;

function ensureSubscribed(): void {
  if (subscribed) return;
  subscribed = true;
  const sub = getRedis().duplicate();
  sub.on('pmessage', (_pattern: string, channel: string) => {
    const set = listeners.get(channel.slice(PREFIX.length));
    if (set) for (const fn of [...set]) fn();
  });
  sub.on('error', (err: Error) => console.error('realtime subscriber error', err.message));
  sub.psubscribe(`${PREFIX}*`).catch((err: Error) => {
    console.error('realtime subscribe failed', err.message);
    subscribed = false;
  });
}

export function publishWake(workspace: string): void {
  getRedis()
    .publish(PREFIX + workspace, '1')
    .catch((err: Error) => console.error('realtime publish failed', err.message));
}

// Returns an unsubscribe function.
export function onWake(workspace: string, fn: Listener): () => void {
  ensureSubscribed();
  let set = listeners.get(workspace);
  if (!set) listeners.set(workspace, (set = new Set()));
  set.add(fn);
  return () => {
    set.delete(fn);
    if (set.size === 0) listeners.delete(workspace);
  };
}

import { getStores, isDuplicateKey } from '../pigeon/store.js';
import { publishWake } from './notify.js';

async function nextSeq(workspace: string): Promise<number> {
  const { counters } = await getStores();
  for (let attempt = 0; attempt < 5; attempt++) {
    try {
      const doc = await counters.findOneAndUpdate({ _id: workspace }, { $inc: { seq: 1 } }, { upsert: true, returnDocument: 'after' });
      if (doc) return doc.seq;
    } catch (err) {
      if (!isDuplicateKey(err)) throw err; // two first-time upserts raced: retry
    }
  }
  throw new Error('could not allocate a sequence number');
}

// Record a change for a workspace and wake every instance. Idempotent on
// (workspace, key): reporting the same change twice (a duplicate webhook, a
// retry after a crash) adds nothing. A rare lost race only skips a seq number.
export async function emitEvent(workspace: string, key: string, frame: Record<string, unknown>): Promise<void> {
  const { realtime } = await getStores();
  if (await realtime.findOne({ workspace, key }, { projection: { _id: 1 } })) return;
  const seq = await nextSeq(workspace);
  try {
    await realtime.insertOne({ workspace, seq, key, frame: { seq, ...frame }, created_at: new Date() });
  } catch (err) {
    if (isDuplicateKey(err)) return;
    throw err;
  }
  publishWake(workspace);
}

export async function currentSeq(workspace: string): Promise<number> {
  const { counters } = await getStores();
  return (await counters.findOne({ _id: workspace }))?.seq ?? 0;
}

export async function eventsAfter(workspace: string, after: number, limit: number): Promise<Array<{ seq: number; frame: Record<string, unknown> }>> {
  const { realtime } = await getStores();
  const rows = await realtime.find({ workspace, seq: { $gt: after } }).sort({ seq: 1 }).limit(limit).toArray();
  return rows.map((r) => ({ seq: r.seq, frame: r.frame }));
}

import type { WebSocket } from 'ws';
import { eventsAfter } from './events.js';
import { onWake } from './notify.js';

const BATCH = 200;
const GAP_RETRY_MS = 100;
const GAP_GIVE_UP_MS = 1500;
const FALLBACK_POLL_MS = 2000;

// Streams a workspace's events to one socket, strictly in seq order, starting
// after `after`. Replay and live delivery are the same loop reading the same
// table, so a frame can neither be sent twice nor fall between the two.
export function startPump(socket: WebSocket, workspace: string, after: number): void {
  let last = after;
  let running = false;
  let again = false;
  let gapSince = 0;
  let closed = false;
  let gapTimer: NodeJS.Timeout | undefined;

  const run = async (): Promise<void> => {
    if (closed) return;
    if (running) {
      again = true;
      return;
    }
    running = true;
    try {
      let more = true;
      while (more && !closed) {
        const events = await eventsAfter(workspace, last, BATCH);
        more = events.length === BATCH;
        for (const e of events) {
          // A higher seq can be visible before a lower one finishes being written.
          // Hold back briefly for the missing one, then move on if it never shows.
          if (e.seq > last + 1) {
            gapSince ||= Date.now();
            if (Date.now() - gapSince < GAP_GIVE_UP_MS) {
              gapTimer ??= setTimeout(() => {
                gapTimer = undefined;
                void run();
              }, GAP_RETRY_MS);
              more = false;
              break;
            }
          }
          gapSince = 0;
          last = e.seq;
          if (socket.readyState === socket.OPEN) socket.send(JSON.stringify(e.frame));
        }
      }
    } catch (err) {
      console.error('socket pump failed', err instanceof Error ? err.message : err);
    } finally {
      running = false;
    }
    if (again) {
      again = false;
      void run();
    }
  };

  const unsubscribe = onWake(workspace, () => void run());
  const poll = setInterval(() => void run(), FALLBACK_POLL_MS); // covers a missed wake-up
  socket.on('close', () => {
    closed = true;
    unsubscribe();
    clearInterval(poll);
    if (gapTimer) clearTimeout(gapTimer);
  });
  socket.on('error', () => socket.close());
  void run();
}

import type { IncomingMessage, Server } from 'node:http';
import type { Duplex } from 'node:stream';
import { WebSocketServer } from 'ws';
import { isMember, sessionFromRequest } from '../auth/middleware.js';
import { currentSeq } from './events.js';
import { startPump } from './pump.js';

function refuse(socket: Duplex, status: string): void {
  socket.write(`HTTP/1.1 ${status}\r\nConnection: close\r\nContent-Length: 0\r\n\r\n`);
  socket.destroy();
}

// GET /ws?workspace=<id>[&after=<seq>]. Same session cookie as the API.
export function attachSockets(server: Server): void {
  const wss = new WebSocketServer({ noServer: true });

  server.on('upgrade', (req: IncomingMessage, socket: Duplex, head: Buffer) => {
    socket.on('error', () => socket.destroy());
    void (async () => {
      const url = new URL(req.url ?? '/', 'http://localhost');
      if (url.pathname !== '/ws') return refuse(socket, '404 Not Found');

      let session;
      try {
        session = await sessionFromRequest(req);
      } catch {
        return refuse(socket, '503 Service Unavailable');
      }
      if (!session) return refuse(socket, '401 Unauthorized');

      const workspace = url.searchParams.get('workspace');
      if (!workspace || !isMember(session, workspace)) return refuse(socket, '403 Forbidden');

      const afterParam = url.searchParams.get('after');
      if (afterParam !== null && !/^\d{1,15}$/.test(afterParam)) return refuse(socket, '400 Bad Request');

      let start: number;
      try {
        // No `after`: live only, from the current position.
        start = afterParam !== null ? Number(afterParam) : await currentSeq(workspace);
      } catch {
        return refuse(socket, '503 Service Unavailable');
      }
      wss.handleUpgrade(req, socket, head, (ws) => startPump(ws, workspace, start));
    })();
  });
}

