    // 1. Signature first, on the raw bytes. Never a 5xx for a bad signature.
    const sig = verifyPigeonSignature(req.header('x-pigeon-signature'), body);
    if (!sig.ok) {
      res.status(401).json({ error: sig.reason });
      return;
    }

