    let parsed: unknown;
    try {
      parsed = JSON.parse(body.toString('utf8'));
    } catch {
      res.status(400).json({ error: 'invalid json' });
      return;
    }
    if (!isObj(parsed)) {
      res.status(400).json({ error: 'body must be an object' });
      return;
