      ...(refundAttempt ? { $inc: { attempts: -1 } } : {}),
    },
  );
}

function backoff(attempts: number): number {
  const exp = Math.min(BACKOFF_MAX_MS, BACKOFF_BASE_MS * 2 ** Math.max(0, attempts - 1));
  return Math.round(exp / 2 + Math.random() * (exp / 2)); // jitter
