import type { Conversation } from './types';

interface Props {
  conversations: Conversation[];
  selected: string | null;
  me: string;
  onSelect: (contact: string) => void;
}

export function ConversationList({ conversations, selected, me, onSelect }: Props) {
  if (!conversations.length) return <p style={{ padding: 12 }}>No conversations yet.</p>;
  return (
    <ul style={{ listStyle: 'none', margin: 0, padding: 0 }}>
      {conversations.map((c) => (
        <li key={c.contact}>
          <button
            onClick={() => onSelect(c.contact)}
            style={{ display: 'block', width: '100%', textAlign: 'left', padding: '8px 12px', border: 0, borderBottom: '1px solid #ddd', background: c.contact === selected ? '#e8f0fe' : 'white', cursor: 'pointer' }}
          >
            <strong>{c.contact}</strong>
            <div style={{ fontSize: 12, color: '#555' }}>
              {c.state === 'closed' ? 'closed' : 'open'} · {c.assignee ? (c.assignee === me ? 'you' : c.assignee) : 'unassigned'}
              {c.last_activity_at ? ` · ${new Date(c.last_activity_at).toLocaleTimeString()}` : ''}
            </div>
          </button>
        </li>
      ))}
    </ul>
  );
}

import { useState } from 'react';
import { api } from './api';
import type { Conversation, ThreadMessage } from './types';

interface Props {
  workspace: string;
  conversation: Conversation;
  messages: ThreadMessage[];
  me: string;
  onChanged: () => void;
}

export function Thread({ workspace, conversation, messages, me, onChanged }: Props) {
  const [text, setText] = useState('');
  const [error, setError] = useState('');
  const { contact } = conversation;

  const run = async (action: () => Promise<unknown>, conflict?: string) => {
    setError('');
    try {
      await action();
      onChanged();
    } catch (e) {
      setError((e as { status?: number }).status === 409 && conflict ? conflict : 'Something went wrong. Try again.');
    }
  };

  const send = (e: React.FormEvent) => {
    e.preventDefault();
    const body = text.trim();
    if (!body) return;
    setText('');
    void run(() => api.reply(workspace, contact, body));
  };

  return (
    <section style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <header style={{ padding: 12, borderBottom: '1px solid #ddd' }}>
        <strong>{contact}</strong> · {conversation.state} · assignee: {conversation.assignee ?? 'none'}
        <span style={{ marginLeft: 12 }}>
          {conversation.assignee !== me && (
            <button onClick={() => run(() => api.claim(workspace, contact), 'Someone else already holds this conversation.')}>Claim</button>
          )}{' '}
          {conversation.state === 'open' ? (
            <button onClick={() => run(() => api.close(workspace, contact))}>Close</button>
          ) : (
            <button onClick={() => run(() => api.reopen(workspace, contact))}>Reopen</button>
          )}
        </span>
        {error && <div style={{ color: 'crimson' }}>{error}</div>}
      </header>
      <div style={{ flex: 1, overflow: 'auto', padding: 12 }}>
        {messages.map((m) => (
          <div key={`${m.direction}:${m.id}`} style={{ textAlign: m.direction === 'out' ? 'right' : 'left', margin: '6px 0' }}>
            <span style={{ display: 'inline-block', padding: '6px 10px', borderRadius: 8, background: m.direction === 'out' ? '#d6e9ff' : '#eee' }}>{m.text}</span>
            <div style={{ fontSize: 11, color: m.status === 'failed' ? 'crimson' : '#777' }}>
              {new Date(m.at).toLocaleTimeString()}
              {m.status ? ` · ${m.status}` : ''}
            </div>
          </div>
        ))}
      </div>
      <form onSubmit={send} style={{ display: 'flex', gap: 8, padding: 12, borderTop: '1px solid #ddd' }}>
        <input value={text} onChange={(e) => setText(e.target.value)} placeholder="Write a reply" style={{ flex: 1 }} />
        <button type="submit">Send</button>
      </form>
    </section>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { api } from './api';
import { ConversationList } from './ConversationList';
import { Thread } from './Thread';
import type { Conversation, Frame, Me, ThreadMessage } from './types';
import { useLive } from './useLive';

export function App() {
  const [me, setMe] = useState<Me | null | undefined>(undefined); // undefined: loading, null: signed out
  const [workspace, setWorkspace] = useState<string | null>(null);
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [selected, setSelected] = useState<string | null>(null);
  const [messages, setMessages] = useState<ThreadMessage[]>([]);

  useEffect(() => {
    api.me().then(
      (m) => {
        setMe(m);
        setWorkspace(m.workspaces[0]?.id ?? null);
      },
      () => setMe(null),
    );
  }, []);

  const loadList = useCallback(() => {
    if (workspace) api.conversations(workspace).then(setConversations, () => undefined);
  }, [workspace]);

  const loadThread = useCallback(() => {
    if (workspace && selected) api.messages(workspace, selected).then(setMessages, () => undefined);
  }, [workspace, selected]);

  useEffect(() => {
    setSelected(null);
    setMessages([]);
    loadList();
  }, [loadList]);

  useEffect(() => {
    setMessages([]);
    loadThread();
  }, [loadThread]);

  // Any change refreshes the list; the open thread refreshes if it was affected.
  useLive(workspace, (f: Frame) => {
    loadList();
    if (f.type === 'reconnected' || f.contact === selected) loadThread();
  });

  if (me === undefined) return <p style={{ padding: 24 }}>Loading…</p>;
  if (me === null) {
    return (
      <main style={{ font: '16px system-ui', maxWidth: 480, margin: '80px auto' }}>
        <h1>Switchboard</h1>
        <a href="/auth/login">Sign in</a>
      </main>
    );
  }

  const current = conversations.find((c) => c.contact === selected);
  return (
    <div style={{ font: '15px system-ui', display: 'grid', gridTemplateColumns: '300px 1fr', gridTemplateRows: 'auto 1fr', height: '100vh' }}>
      <header style={{ gridColumn: '1 / 3', padding: 10, borderBottom: '1px solid #ccc', display: 'flex', gap: 12, alignItems: 'center' }}>
        <strong>Switchboard</strong>
        <span>{me.name ?? me.sub}</span>
        <label>
          Workspace{' '}
          <select value={workspace ?? ''} onChange={(e) => setWorkspace(e.target.value)}>
            {me.workspaces.map((w) => (
              <option key={w.id} value={w.id}>
                {w.id} ({w.role})
              </option>
            ))}
          </select>
        </label>
      </header>
      <nav style={{ overflow: 'auto', borderRight: '1px solid #ccc' }}>
        <ConversationList conversations={conversations} selected={selected} me={me.sub} onSelect={setSelected} />
      </nav>
      <main style={{ minHeight: 0 }}>
        {workspace && current ? (
          <Thread workspace={workspace} conversation={current} messages={messages} me={me.sub} onChanged={() => { loadList(); loadThread(); }} />
        ) : (
          <p style={{ padding: 12 }}>Select a conversation.</p>
        )}
      </main>
    </div>
  );
}

